//! Transactional cache-group certificate layer.
//!
//! The ledger keeps the last committed configuration plus every aggregate that
//! a certificate or a proposal-violation count needs, updates those aggregates
//! incrementally while a proposal is applied, and replays a bounded undo log
//! when the proposal is rejected.  Committed state is therefore never lost.

use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};

use crate::solver::SolverProblem;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

/// Cheap integer hasher; the map keys are dense small integers.
#[derive(Default, Clone, Copy)]
struct FxHasher { h: u64 }
impl Hasher for FxHasher {
    #[inline]
    fn write(&mut self, bytes: &[u8]) { for &b in bytes { self.write_u64(b as u64); } }
    #[inline]
    fn write_u64(&mut self, n: u64) { self.h = (self.h ^ n).wrapping_mul(0x0100_0000_01b3); }
    #[inline]
    fn write_u32(&mut self, n: u32) { self.write_u64(n as u64); }
    #[inline]
    fn finish(&self) -> u64 {
        let mut h = self.h;
        h ^= h >> 33;
        h = h.wrapping_mul(0xff51_afd7_ed55_8ccd);
        h ^= h >> 33;
        h
    }
}
/// (domain << 32) | class  ->  number of member tasks with that pair.
type PairMap = HashMap<u64, u32, BuildHasherDefault<FxHasher>>;

#[inline]
fn pair_key(domain: u32, class: u64) -> u64 { ((domain as u64) << 32) | (class & 0xffff_ffff) }

#[derive(Clone, Copy)]
struct GroupSnap {
    g: u32, off: u32, fp_size: u32, count: u32,
    load: u64, quota: u64, budget: u64, bad: bool, mixed: bool,
}

#[derive(Clone, Copy)]
struct NodeSnap { v: u32, usage: u64, cap: u64, over: bool }

#[derive(Clone, Copy)]
struct Counters {
    cap_v: u64, mixed_v: u64, work_v: u64,
    active: u64, slots: u64, weight: u64, pinned: u64,
}

pub struct Ledger {
    n: usize,
    groups: usize,
    words: usize,
    /// template footprints as flat bitsets, `words` u64 per template
    fp: Vec<u64>,
    /// template domain (source group / scope id)
    domain: Vec<u32>,

    tasks: Vec<Task>,
    quota: Vec<u64>,
    budget: Vec<u64>,
    caps: Vec<u64>,

    /// cnt[g*n+v]: member tasks of group g whose template footprint holds v
    cnt: Vec<u32>,
    fp_size: Vec<u32>,
    load: Vec<u64>,
    count: Vec<u32>,
    pairs: Vec<PairMap>,

    usage: Vec<u64>,
    over: Vec<bool>,
    bad: Vec<bool>,
    mixed: Vec<bool>,

    cap_v: u64,
    mixed_v: u64,
    work_v: u64,
    active: u64,
    slots: u64,
    weight_total: u64,
    pinned_total: u64,

    revision: u64,

    /// committed pin state (start-of-transaction view)
    cpinned: Vec<bool>,
    cpinned_count: Vec<u32>,

    tx: u32,
    task_stamp: Vec<u32>,
    group_stamp: Vec<u32>,
    node_stamp: Vec<u32>,
    qmark: Vec<u32>,
    undo_tasks: Vec<(u32, Task)>,
    undo_groups: Vec<GroupSnap>,
    undo_rows: Vec<u32>,
    undo_nodes: Vec<NodeSnap>,
    undo_pairs: Vec<(u32, u64, u32)>,
    counters: Counters,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let n = problem.num_nodes;
        if n == 0 || n > 343 { return Err("node count out of range".into()); }
        if capacities.len() != n { return Err("capacity count".into()); }
        let templates = problem.demands.len();
        let group_count = quotas.len();
        if group_count == 0 || group_count > 8192 || budgets.len() != group_count {
            return Err("group count".into());
        }
        let words = (n + 63) / 64;
        if words > 6 { return Err("footprint width".into()); }

        let domain = template_domains(problem, n, templates)?;
        let mut fp = vec![0u64; templates * words];
        for (id, demand) in problem.demands.iter().enumerate() {
            for &node in demand.footprint.iter() {
                if node >= n { return Err("footprint node".into()); }
                fp[id * words + node / 64] |= 1u64 << (node % 64);
            }
        }

        let task_count = tasks.len();
        for task in tasks.iter() {
            if task.template >= templates || task.group >= group_count {
                return Err("task reference".into());
            }
            if task.class > u32::MAX as u64 { return Err("task class".into()); }
        }

        let mut led = Ledger {
            n,
            groups: group_count,
            words,
            fp,
            domain,
            tasks,
            quota: quotas,
            budget: budgets,
            caps: capacities,
            cnt: vec![0u32; group_count * n],
            fp_size: vec![0u32; group_count],
            load: vec![0u64; group_count],
            count: vec![0u32; group_count],
            pairs: (0..group_count).map(|_| PairMap::default()).collect(),
            usage: vec![0u64; n],
            over: vec![false; n],
            bad: vec![false; group_count],
            mixed: vec![false; group_count],
            cap_v: 0, mixed_v: 0, work_v: 0,
            active: 0, slots: 0, weight_total: 0, pinned_total: 0,
            revision: 0,
            cpinned: vec![false; task_count],
            cpinned_count: vec![0u32; group_count],
            tx: 0,
            task_stamp: vec![0u32; task_count],
            group_stamp: vec![0u32; group_count],
            node_stamp: vec![0u32; n],
            qmark: vec![0u32; group_count],
            undo_tasks: Vec::new(),
            undo_groups: Vec::new(),
            undo_rows: Vec::new(),
            undo_nodes: Vec::new(),
            undo_pairs: Vec::new(),
            counters: Counters { cap_v: 0, mixed_v: 0, work_v: 0, active: 0, slots: 0, weight: 0, pinned: 0 },
        };
        led.build_initial()?;
        Ok(led)
    }

    fn build_initial(&mut self) -> Result<(), String> {
        let n = self.n;
        let words = self.words;
        for id in 0..self.tasks.len() {
            let task = self.tasks[id];
            let g = task.group;
            self.count[g] += 1;
            self.load[g] += task.weight;
            self.weight_total += task.weight;
            if task.pinned {
                self.pinned_total += 1;
                self.cpinned[id] = true;
                self.cpinned_count[g] += 1;
            }
            let key = pair_key(self.domain[task.template], task.class);
            *self.pairs[g].entry(key).or_insert(0) += 1;
            let base = g * n;
            let start = task.template * words;
            for wi in 0..words {
                let mut word = self.fp[start + wi];
                while word != 0 {
                    let bit = word.trailing_zeros() as usize;
                    word &= word - 1;
                    let idx = base + wi * 64 + bit;
                    self.cnt[idx] = self.cnt[idx].checked_add(1).ok_or("footprint multiplicity")?;
                }
            }
        }
        for g in 0..self.groups {
            let mut size = 0u32;
            for v in 0..n { if self.cnt[g * n + v] > 0 { size += 1; } }
            self.fp_size[g] = size;
            if self.count[g] > 0 { self.active += 1; }
            self.mixed[g] = self.pairs[g].len() > 1;
            if self.mixed[g] { self.mixed_v += 1; }
            self.bad[g] = self.work_bad(g);
            if self.bad[g] { self.work_v += 1; }
        }
        for v in 0..n {
            let mut used = 0u64;
            for g in 0..self.groups { if self.cnt[g * n + v] > 0 { used += self.quota[g]; } }
            self.usage[v] = used;
            self.slots += used;
            self.over[v] = used > self.caps[v];
            if self.over[v] { self.cap_v += 1; }
        }
        if self.cap_v != 0 || self.mixed_v != 0 || self.work_v != 0 {
            return Err("illegal initial configuration".into());
        }
        Ok(())
    }

    #[inline]
    fn work_bad(&self, g: usize) -> bool {
        self.count[g] > 0
            && (self.quota[g] == 0
                || self.load[g] > self.quota[g].saturating_mul(self.budget[g]))
    }

    #[inline]
    fn refresh_work(&mut self, g: usize) {
        let bad = self.work_bad(g);
        if bad != self.bad[g] {
            self.bad[g] = bad;
            if bad { self.work_v += 1; } else { self.work_v -= 1; }
        }
    }

    #[inline]
    fn refresh_mixed(&mut self, g: usize) {
        let mixed = self.pairs[g].len() > 1;
        if mixed != self.mixed[g] {
            self.mixed[g] = mixed;
            if mixed { self.mixed_v += 1; } else { self.mixed_v -= 1; }
        }
    }

    fn touch_task(&mut self, t: usize) {
        if self.task_stamp[t] != self.tx {
            self.task_stamp[t] = self.tx;
            self.undo_tasks.push((t as u32, self.tasks[t]));
        }
    }

    fn touch_group(&mut self, g: usize) {
        if self.group_stamp[g] != self.tx {
            self.group_stamp[g] = self.tx;
            let off = self.undo_rows.len() as u32;
            let n = self.n;
            self.undo_rows.extend_from_slice(&self.cnt[g * n..g * n + n]);
            self.undo_groups.push(GroupSnap {
                g: g as u32,
                off,
                fp_size: self.fp_size[g],
                count: self.count[g],
                load: self.load[g],
                quota: self.quota[g],
                budget: self.budget[g],
                bad: self.bad[g],
                mixed: self.mixed[g],
            });
        }
    }

    fn touch_node(&mut self, v: usize) {
        if self.node_stamp[v] != self.tx {
            self.node_stamp[v] = self.tx;
            self.undo_nodes.push(NodeSnap { v: v as u32, usage: self.usage[v], cap: self.caps[v], over: self.over[v] });
        }
    }

    fn set_usage(&mut self, v: usize, next: u64) {
        self.touch_node(v);
        let old = self.usage[v];
        if old == next { return; }
        self.usage[v] = next;
        self.slots = (self.slots as i128 + next as i128 - old as i128) as u64;
        let over = next > self.caps[v];
        if over != self.over[v] {
            self.over[v] = over;
            if over { self.cap_v += 1; } else { self.cap_v -= 1; }
        }
    }

    /// Add (+) or remove (-) one task's template footprint from a group's
    /// per-node reservation counters.
    fn attach(&mut self, template: usize, g: usize, add: bool) {
        self.touch_group(g);
        let words = self.words;
        let mut buf = [0u64; 6];
        let start = template * words;
        buf[..words].copy_from_slice(&self.fp[start..start + words]);
        let quota = self.quota[g];
        let base = g * self.n;
        for wi in 0..words {
            let mut word = buf[wi];
            while word != 0 {
                let bit = word.trailing_zeros() as usize;
                word &= word - 1;
                let v = wi * 64 + bit;
                let idx = base + v;
                let old = self.cnt[idx];
                let next = if add { old + 1 } else { old - 1 };
                self.cnt[idx] = next;
                if (old == 0) != (next == 0) {
                    if add { self.fp_size[g] += 1; } else { self.fp_size[g] -= 1; }
                    let used = self.usage[v];
                    let next_used = if add { used + quota } else { used - quota };
                    self.set_usage(v, next_used);
                }
            }
        }
    }

    fn pair_inc(&mut self, g: usize, key: u64) {
        self.touch_group(g);
        let old = self.pairs[g].get(&key).copied().unwrap_or(0);
        self.undo_pairs.push((g as u32, key, old));
        if old == 0 {
            self.pairs[g].insert(key, 1);
            self.refresh_mixed(g);
        } else {
            self.pairs[g].insert(key, old + 1);
        }
    }

    fn pair_dec(&mut self, g: usize, key: u64) {
        self.touch_group(g);
        let old = self.pairs[g].get(&key).copied().unwrap_or(0);
        self.undo_pairs.push((g as u32, key, old));
        if old <= 1 {
            self.pairs[g].remove(&key);
            self.refresh_mixed(g);
        } else {
            self.pairs[g].insert(key, old - 1);
        }
    }

    fn apply(&mut self, edit: &Edit) {
        match *edit {
            Edit::Move(t, to) => {
                if t >= self.tasks.len() || to >= self.groups { return; }
                self.touch_task(t);
                let task = self.tasks[t];
                let from = task.group;
                if from == to { return; }
                let key = pair_key(self.domain[task.template], task.class);
                self.touch_group(from);
                self.count[from] -= 1;
                if self.count[from] == 0 { self.active -= 1; }
                self.load[from] -= task.weight;
                self.pair_dec(from, key);
                self.attach(task.template, from, false);
                self.refresh_work(from);
                self.touch_group(to);
                if self.count[to] == 0 { self.active += 1; }
                self.count[to] += 1;
                self.load[to] += task.weight;
                self.pair_inc(to, key);
                self.attach(task.template, to, true);
                self.refresh_work(to);
                self.tasks[t].group = to;
            }
            Edit::Weight(t, weight) => {
                if t >= self.tasks.len() { return; }
                self.touch_task(t);
                let old = self.tasks[t].weight;
                if old == weight { return; }
                self.tasks[t].weight = weight;
                self.weight_total = (self.weight_total as i128 + weight as i128 - old as i128) as u64;
                let g = self.tasks[t].group;
                self.touch_group(g);
                self.load[g] = (self.load[g] as i128 + weight as i128 - old as i128) as u64;
                self.refresh_work(g);
            }
            Edit::Class(t, class) => {
                if t >= self.tasks.len() || class > u32::MAX as u64 { return; }
                self.touch_task(t);
                let old = self.tasks[t].class;
                if old == class { return; }
                let g = self.tasks[t].group;
                let domain = self.domain[self.tasks[t].template];
                self.pair_dec(g, pair_key(domain, old));
                self.pair_inc(g, pair_key(domain, class));
                self.tasks[t].class = class;
            }
            Edit::Bind(t, template) => {
                if t >= self.tasks.len() || template * self.words + self.words > self.fp.len() { return; }
                self.touch_task(t);
                let old = self.tasks[t].template;
                if old == template { return; }
                let g = self.tasks[t].group;
                let class = self.tasks[t].class;
                self.attach(old, g, false);
                self.attach(template, g, true);
                let before = pair_key(self.domain[old], class);
                let after = pair_key(self.domain[template], class);
                if before != after {
                    self.pair_dec(g, before);
                    self.pair_inc(g, after);
                }
                self.tasks[t].template = template;
            }
            Edit::Pin(t, pinned) => {
                if t >= self.tasks.len() { return; }
                self.touch_task(t);
                if self.tasks[t].pinned != pinned {
                    self.tasks[t].pinned = pinned;
                    if pinned { self.pinned_total += 1; } else { self.pinned_total -= 1; }
                }
            }
            Edit::Quota(g, quota) => {
                if g >= self.groups { return; }
                self.touch_group(g);
                let old = self.quota[g];
                if old == quota { return; }
                self.quota[g] = quota;
                let base = g * self.n;
                for v in 0..self.n {
                    if self.cnt[base + v] > 0 {
                        let next = self.usage[v] - old + quota;
                        self.set_usage(v, next);
                    }
                }
                self.refresh_work(g);
            }
            Edit::Budget(g, budget) => {
                if g >= self.groups { return; }
                self.touch_group(g);
                self.budget[g] = budget;
                self.refresh_work(g);
            }
            Edit::Cap(v, cap) => {
                if v >= self.n { return; }
                self.touch_node(v);
                self.caps[v] = cap;
                let over = self.usage[v] > cap;
                if over != self.over[v] {
                    self.over[v] = over;
                    if over { self.cap_v += 1; } else { self.cap_v -= 1; }
                }
            }
        }
    }

    fn begin_tx(&mut self) {
        self.tx = self.tx.wrapping_add(1);
        if self.tx == 0 { self.tx = 1; }
        self.undo_tasks.clear();
        self.undo_groups.clear();
        self.undo_rows.clear();
        self.undo_nodes.clear();
        self.undo_pairs.clear();
        self.counters = Counters {
            cap_v: self.cap_v,
            mixed_v: self.mixed_v,
            work_v: self.work_v,
            active: self.active,
            slots: self.slots,
            weight: self.weight_total,
            pinned: self.pinned_total,
        };
    }

    fn rollback(&mut self) {
        for i in (0..self.undo_pairs.len()).rev() {
            let (g, key, old) = self.undo_pairs[i];
            let g = g as usize;
            if old == 0 { self.pairs[g].remove(&key); } else { self.pairs[g].insert(key, old); }
        }
        let n = self.n;
        for i in 0..self.undo_groups.len() {
            let snap = self.undo_groups[i];
            let g = snap.g as usize;
            let off = snap.off as usize;
            self.fp_size[g] = snap.fp_size;
            self.count[g] = snap.count;
            self.load[g] = snap.load;
            self.quota[g] = snap.quota;
            self.budget[g] = snap.budget;
            self.bad[g] = snap.bad;
            self.mixed[g] = snap.mixed;
            self.cnt[g * n..g * n + n].copy_from_slice(&self.undo_rows[off..off + n]);
        }
        for i in 0..self.undo_nodes.len() {
            let snap = self.undo_nodes[i];
            let v = snap.v as usize;
            self.usage[v] = snap.usage;
            self.caps[v] = snap.cap;
            self.over[v] = snap.over;
        }
        for i in 0..self.undo_tasks.len() {
            let (t, task) = self.undo_tasks[i];
            self.tasks[t as usize] = task;
        }
        let c = self.counters;
        self.cap_v = c.cap_v;
        self.mixed_v = c.mixed_v;
        self.work_v = c.work_v;
        self.active = c.active;
        self.slots = c.slots;
        self.weight_total = c.weight;
        self.pinned_total = c.pinned;
    }

    /// Exact number of protected tasks whose final proposal differs in group,
    /// template, weight, class or old-group quota.  Each task counts once.
    fn pin_violations(&mut self) -> u64 {
        let mut quota_groups = 0u64;
        for i in 0..self.undo_groups.len() {
            let snap = self.undo_groups[i];
            let g = snap.g as usize;
            if self.quota[g] != snap.quota {
                self.qmark[g] = self.tx;
                quota_groups += self.cpinned_count[g] as u64;
            }
        }
        let mut edited = 0u64;
        let mut both = 0u64;
        for i in 0..self.undo_tasks.len() {
            let (id, start) = self.undo_tasks[i];
            let t = id as usize;
            if !self.cpinned[t] { continue; }
            let now = self.tasks[t];
            if now.group != start.group
                || now.template != start.template
                || now.weight != start.weight
                || now.class != start.class
            {
                edited += 1;
                if self.qmark[start.group] == self.tx { both += 1; }
            }
        }
        edited + quota_groups - both
    }

    /// Move the accepted pin flags/groups into the committed pin view.
    fn commit_pins(&mut self) {
        for i in 0..self.undo_tasks.len() {
            let (id, start) = self.undo_tasks[i];
            let t = id as usize;
            if self.cpinned[t] { self.cpinned_count[start.group] -= 1; }
            let pinned = self.tasks[t].pinned;
            self.cpinned[t] = pinned;
            if pinned { self.cpinned_count[self.tasks[t].group] += 1; }
        }
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let totals = [self.active, self.slots, self.weight_total, self.pinned_total];
        let mut groups = Vec::with_capacity(query.groups.len());
        for &id in query.groups.iter() {
            let (domain, class) = if self.count[id] == 0 {
                (-1i64, -1i64)
            } else {
                match self.pairs[id].iter().next() {
                    Some((&key, _)) => (((key >> 32) & 0xffff_ffff) as i64, (key & 0xffff_ffff) as i64),
                    None => (-1i64, -1i64),
                }
            };
            groups.push([
                id as i64,
                self.count[id] as i64,
                self.load[id] as i64,
                self.quota[id] as i64,
                self.budget[id] as i64,
                self.fp_size[id] as i64,
                domain,
                class,
            ]);
        }
        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &id in query.nodes.iter() {
            nodes.push([id as u64, self.usage[id], self.caps[id]]);
        }
        let mut tasks = Vec::with_capacity(query.tasks.len());
        for &id in query.tasks.iter() {
            let task = self.tasks[id];
            tasks.push([id as u64, task.group as u64, task.template as u64, task.weight, task.class, task.pinned as u64]);
        }
        Certificate { totals, groups, nodes, tasks }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate: self.certificate(query),
            };
        }
        self.begin_tx();
        for edit in edits { self.apply(edit); }
        let pins = self.pin_violations();
        let violations = [self.cap_v, self.mixed_v, self.work_v, pins];
        let accepted = violations.iter().all(|&v| v == 0);
        if accepted {
            self.commit_pins();
            self.revision += 1;
        } else {
            self.rollback();
        }
        let certificate = self.certificate(query);
        Outcome { accepted, revision: self.revision, violations: Some(violations), certificate }
    }
}

/// Template domain ids: explicit per-template classes when the topology scope
/// needs them, otherwise the index of the source merge group of the source.
fn template_domains(problem: &SolverProblem, n: usize, templates: usize) -> Result<Vec<u32>, String> {
    if let Some(classes) = problem.demand_merge_classes.as_ref() {
        if classes.len() != templates { return Err("merge class count".into()); }
        let mut domain = Vec::with_capacity(templates);
        for &class in classes.iter() {
            if class as u64 > u32::MAX as u64 { return Err("merge class range".into()); }
            domain.push(class as u32);
        }
        return Ok(domain);
    }
    let mut owner = vec![usize::MAX; n];
    for (id, members) in problem.source_merge_groups.iter().enumerate() {
        for &node in members.iter() {
            if node >= n { return Err("source merge group node".into()); }
            if owner[node] != usize::MAX { return Err("overlapping source merge groups".into()); }
            owner[node] = id;
        }
    }
    let mut domain = Vec::with_capacity(templates);
    for demand in problem.demands.iter() {
        if demand.src >= n { return Err("template source".into()); }
        let id = owner[demand.src];
        if id == usize::MAX || id > u32::MAX as usize { return Err("template domain".into()); }
        domain.push(id as u32);
    }
    Ok(domain)
}
