"""Independent Python implementation of the documented topology templates."""
from collections import deque

def _bfs_footprints(n, adj, endpoints):
    dist = []
    for s in range(n):
        d = [-1]*n; d[s] = 0; q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if d[v] < 0:
                    d[v] = d[u]+1; q.append(v)
        dist.append(d)
    out = []
    for s in endpoints:
        for t in endpoints:
            if s == t: continue
            best = dist[s][t]
            fp = [v for v in range(n) if dist[s][v] >= 0 and dist[s][v]+dist[v][t] == best]
            out.append((s, t, sorted(fp)))
    return out

def build(spec):
    """Return (num_nodes, templates, domains); templates = [(src,dst,footprint)] ascending."""
    mode = spec[0]
    if mode == 'clos':
        _, k, scope, intra = spec
        r = k//2; T = k*r; n = k*k
        tors = list(range(T))
        tmpl = []
        for s in tors:
            for d in tors:
                if s == d: continue
                if not intra and s//r == d//r: continue
                fp = {s, d}
                for off in range(r):
                    fp.add(T + (s//r)*r + off)
                    fp.add(T + (d//r)*r + off)
                tmpl.append((s, d, sorted(fp)))
        dom = [(s if scope == 'tor' else s//r) for (s, d, f) in tmpl]
        return n, tmpl, dom
    if mode == 'leaf-spine':
        _, leaves, spines = spec
        n = leaves+spines
        tmpl = []; dom = []
        for s in range(leaves):
            for d in range(leaves):
                if s == d: continue
                tmpl.append((s, d, sorted([s, d]))); dom.append(s)
        return n, tmpl, dom
    if mode in ('torus2d', 'torus3d'):
        _, side, scope = spec
        dim = 2 if mode == 'torus2d' else 3
        n = side**dim
        adj = [[] for _ in range(n)]
        def coords(u):
            c = []
            for _ in range(dim):
                c.append(u % side); u //= side
            return c
        def ident(c):
            u = 0
            for i in range(dim-1, -1, -1):
                u = u*side + c[i]
            return u
        for u in range(n):
            c = coords(u)
            for ax in range(dim):
                for step in (1, -1):
                    c2 = list(c); c2[ax] = (c2[ax]+step) % side
                    v = ident(c2)
                    if v != u: adj[u].append(v)
        for a in adj: a.sort()
        tmpl = _bfs_footprints(n, adj, range(n))
        dom = []
        for (s, d, f) in tmpl:
            c = coords(s)
            if scope == 'host': dom.append(s)
            elif scope == 'row': dom.append(c[1])
            else: dom.append(c[2]*side + c[1])
        return n, tmpl, dom
    if mode == 'dragonfly':
        _, g, a, h, scope = spec
        n = g*a
        adj = [[] for _ in range(n)]
        rid = lambda grp, i: grp*a + i
        for grp in range(g):
            for i in range(a):
                for j in range(i+1, a):
                    adj[rid(grp, i)].append(rid(grp, j)); adj[rid(grp, j)].append(rid(grp, i))
        for i in range(g):
            for j in range(i+1, g):
                delta = j-i
                u = rid(i, (delta-1)//h); v = rid(j, (g-delta-1)//h)
                adj[u].append(v); adj[v].append(u)
        for x in adj: x.sort()
        tmpl = _bfs_footprints(n, adj, range(n))
        dom = []
        for (s, d, f) in tmpl:
            if scope == 'router': dom.append(s)
            elif scope == 'group': dom.append(s//a)
            else: dom.append(s*g + d//a)
        return n, tmpl, dom
    if mode == 'dragonfly-plus':
        _, g, l, s, h, dense, scope = spec
        per = l+s; n = g*per
        leaf_id = lambda grp, i: grp*per + i
        spine_id = lambda grp, i: grp*per + l + i
        adj = [[] for _ in range(n)]
        for grp in range(g):
            for i in range(l):
                for j in range(s):
                    u = leaf_id(grp, i); v = spine_id(grp, j)
                    adj[u].append(v); adj[v].append(u)
        if dense:
            for i in range(g):
                for j in range(i+1, g):
                    for k in range(s):
                        u = spine_id(i, k); v = spine_id(j, k)
                        adj[u].append(v); adj[v].append(u)
        else:
            for i in range(g):
                for j in range(i+1, g):
                    delta = j-i
                    u = spine_id(i, (delta-1)//h); v = spine_id(j, (g-delta-1)//h)
                    adj[u].append(v); adj[v].append(u)
        for x in adj: x.sort()
        endpoints = [leaf_id(grp, i) for grp in range(g) for i in range(l)]
        tmpl = _bfs_footprints(n, adj, endpoints)
        dom = []
        for (src, dst, f) in tmpl:
            if scope == 'group': dom.append(src//per)
            else: dom.append((src//per)*l + (src % per))
        return n, tmpl, dom
    raise ValueError('topology')
