def gen_session(rng, illegal=False, ntx=12, ntasks=None, ngroups=None):
    spec = rng.choice(SMALL)
    n, tmpl, dom = topo.build(spec)
    T = len(tmpl)
    fps = [set(f) for (s, d, f) in tmpl]
    G = ngroups if ngroups is not None else rng.randint(1, 6)
    D = ntasks if ntasks is not None else rng.randint(0, 14)
    by_domain = {}
    for i, d in enumerate(dom):
        by_domain.setdefault(d, []).append(i)
    domains = sorted(by_domain)

    groups = []
    assign = []          # (domain, class) fixed per group, or None => group stays empty
    for g in range(G):
        groups.append([rng.choice([0, 1, 1, 2, 3, 5, 8, 12]), rng.choice([1, 2, 5, 100, 10**6, 10**9])])
        if domains and rng.random() < 0.85:
            assign.append((rng.choice(domains), rng.randint(0, 4)))
        else:
            assign.append(None)

    tasks = []
    load = [0]*G
    for t in range(D):
        g = rng.randrange(G)
        a = assign[g]
        if a is None:
            a = (rng.choice(domains), rng.randint(0, 4))
            assign[g] = a
        tpl = rng.choice(by_domain[a[0]])
        w = rng.randint(1, 30)
        tasks.append([tpl, g, w, a[1], 1 if rng.random() < 0.3 else 0])
        load[g] += w

    # make work constraints hold
    for g in range(G):
        if load[g] > 0:
            if groups[g][0] == 0:
                groups[g][0] = rng.randint(1, 4)
            need = -(-load[g] // groups[g][0])
            if groups[g][1] < need:
                groups[g][1] = need
    # capacities from exact usage + small slack (tight, exercises capacity edge)
    foot = [set() for _ in range(G)]
    for (tpl, g, w, c, p) in tasks:
        foot[g] |= fps[tpl]
    caps = []
    for v in range(n):
        used = sum(groups[g][0] for g in range(G) if foot[g] and v in foot[g])
        caps.append(used + rng.choice([0, 0, 0, 1, 3]))

    if illegal:
        kind = rng.randrange(3)
        if kind == 0 and n:
            caps[rng.randrange(n)] = 0
            if all(c == 0 for c in caps):
                caps[0] = 10**9
        elif kind == 1 and G:
            g = rng.randrange(G)
            groups[g][1] = 1
            groups[g][0] = 0
        else:
            g = rng.randrange(G)
            groups[g][0] = 0

    def query():
        return {'groups': [rng.randrange(G) for _ in range(rng.randint(0, 4))],
                'nodes': [rng.randrange(n) for _ in range(rng.randint(0, 4))],
                'tasks': [rng.randrange(D) for _ in range(rng.randint(0, 4))] if D else []}

    transactions = []
    rev = 0
    for _ in range(rng.randint(0, ntx)):
        if rng.random() < 0.25:
            r = max(0, rev + rng.choice([-1, 1, 2, 100]))
        else:
            r = rev
        edits = []
        for _ in range(rng.randint(0, 6)):
            kind = rng.choice(['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap',
                               'move', 'bind', 'pin', 'quota'])
            if not D and kind in ('move', 'weight', 'class', 'bind', 'pin'):
                continue
            if kind == 'move': edits.append([kind, rng.randrange(D), rng.randrange(G)])
            elif kind == 'weight': edits.append([kind, rng.randrange(D), rng.randint(1, 60)])
            elif kind == 'class': edits.append([kind, rng.randrange(D), rng.randint(0, 4)])
            elif kind == 'bind': edits.append([kind, rng.randrange(D), rng.randrange(T)])
            elif kind == 'pin': edits.append([kind, rng.randrange(D), rng.randint(0, 1)])
            elif kind == 'quota': edits.append([kind, rng.randrange(G), rng.randint(0, 12)])
            elif kind == 'budget': edits.append([kind, rng.randrange(G), rng.randint(1, 10**6)])
            else: edits.append([kind, rng.randrange(n), rng.randint(0, 60)])
        transactions.append({'revision': r, 'edits': edits, 'query': query()})
        rev += 1
    return {'topology': spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': query(), 'transactions': transactions}


def gen_request(seed, sessions=2, illegal=False):
    rng = random.Random(seed)
    return {'version': 2, 'sessions': [gen_session(rng, illegal=illegal) for _ in range(sessions)]}
