    undo_tasks: Vec<(u32, Task)>,
    undo_groups: Vec<GroupSnap>,
    undo_rows: Vec<u32>,
    undo_nodes: Vec<NodeSnap>,
    undo_pairs: Vec<(u32, u64, u32)>,
    counters: Counters,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let n = problem.num_nodes;
        if n == 0 || n > 343 { return Err("node count out of range".into()); }
        if capacities.len() != n { return Err("capacity count".into()); }
        let templates = problem.demands.len();
        let group_count = quotas.len();
        if group_count == 0 || group_count > 8192 || budgets.len() != group_count {
            return Err("group count".into());
        }
        let words = (n + 63) / 64;
        if words > 6 { return Err("footprint width".into()); }

        let domain = template_domains(problem, n, templates)?;
        let mut fp = vec![0u64; templates * words];
        for (id, demand) in problem.demands.iter().enumerate() {
            for &node in demand.footprint.iter() {
                if node >= n { return Err("footprint node".into()); }
                fp[id * words + node / 64] |= 1u64 << (node % 64);
            }
        }

        let task_count = tasks.len();
        for task in tasks.iter() {
            if task.template >= templates || task.group >= group_count {
                return Err("task reference".into());
            }
            if task.class > u32::MAX as u64 { return Err("task class".into()); }
        }

        let mut led = Ledger {
            n,
            groups: group_count,
            words,
            fp,
            domain,
            tasks,
            quota: quotas,
            budget: budgets,
            caps: capacities,
            cnt: vec![0u32; group_count * n],
            fp_size: vec![0u32; group_count],
            load: vec![0u64; group_count],
            count: vec![0u32; group_count],
            pairs: (0..group_count).map(|_| PairMap::default()).collect(),
            usage: vec![0u64; n],
            over: vec![false; n],
            bad: vec![false; group_count],
            mixed: vec![false; group_count],
            cap_v: 0, mixed_v: 0, work_v: 0,
            active: 0, slots: 0, weight_total: 0, pinned_total: 0,
            revision: 0,
            cpinned: vec![false; task_count],
            cpinned_count: vec![0u32; group_count],
            tx: 0,
            task_stamp: vec![0u32; task_count],
            group_stamp: vec![0u32; group_count],
            node_stamp: vec![0u32; n],
            qmark: vec![0u32; group_count],
            undo_tasks: Vec::new(),
            undo_groups: Vec::new(),
            undo_rows: Vec::new(),
            undo_nodes: Vec::new(),
            undo_pairs: Vec::new(),
            counters: Counters { cap_v: 0, mixed_v: 0, work_v: 0, active: 0, slots: 0, weight: 0, pinned: 0 },
        };
        led.build_initial()?;
        Ok(led)
    }

    fn build_initial(&mut self) -> Result<(), String> {
        let n = self.n;
        let words = self.words;
        for id in 0..self.tasks.len() {
            let task = self.tasks[id];
            let g = task.group;
            self.count[g] += 1;
            self.load[g] += task.weight;
            self.weight_total += task.weight;
            if task.pinned {
                self.pinned_total += 1;
                self.cpinned[id] = true;
                self.cpinned_count[g] += 1;
            }
            let key = pair_key(self.domain[task.template], task.class);
            *self.pairs[g].entry(key).or_insert(0) += 1;
            let base = g * n;
            let start = task.template * words;
            for wi in 0..words {
                let mut word = self.fp[start + wi];
                while word != 0 {
                    let bit = word.trailing_zeros() as usize;
                    word &= word - 1;
                    let idx = base + wi * 64 + bit;
                    self.cnt[idx] = self.cnt[idx].checked_add(1).ok_or("footprint multiplicity")?;
                }
            }
        }
        for g in 0..self.groups {
            let mut size = 0u32;
            for v in 0..n { if self.cnt[g * n + v] > 0 { size += 1; } }
            self.fp_size[g] = size;
            if self.count[g] > 0 { self.active += 1; }
            self.mixed[g] = self.pairs[g].len() > 1;
            if self.mixed[g] { self.mixed_v += 1; }
            self.bad[g] = self.work_bad(g);
            if self.bad[g] { self.work_v += 1; }
        }
        for v in 0..n {
            let mut used = 0u64;
            for g in 0..self.groups { if self.cnt[g * n + v] > 0 { used += self.quota[g]; } }
            self.usage[v] = used;
            self.slots += used;
            self.over[v] = used > self.caps[v];
            if self.over[v] { self.cap_v += 1; }
        }
        if self.cap_v != 0 || self.mixed_v != 0 || self.work_v != 0 {
            return Err("illegal initial configuration".into());
        }
        Ok(())
    }

    #[inline]
    fn work_bad(&self, g: usize) -> bool {
        self.count[g] > 0
            && (self.quota[g] == 0
                || self.load[g] > self.quota[g].saturating_mul(self.budget[g]))

fn apply(&mut self, edit: &Edit) {
    match *edit {
        Edit::Move(t, to) => {
            if t >= self.tasks.len() || to >= self.groups { return; }
            self.touch_task(t);
            let task = self.tasks[t];
            let from = task.group;
            if from == to { return; }
            let key = pair_key(self.domain[task.template], task.class);
            self.touch_group(from);
            self.count[from] -= 1;
            if self.count[from] == 0 { self.active -= 1; }
            self.load[from] -= task.weight;
            self.pair_dec(from, key);
            self.attach(task.template, from, false);
            self.refresh_work(from);
            self.touch_group(to);
            if self.count[to] == 0 { self.active += 1; }
            self.count[to] += 1;
            self.load[to] += task.weight;
            self.pair_inc(to, key);
            self.attach(task.template, to, true);
            self.refresh_work(to);
            self.tasks[t].group = to;
        }
        Edit::Weight(t, weight) => {
            if t >= self.tasks.len() { return; }
            self.touch_task(t);
            let old = self.tasks[t].weight;
            if old == weight { return; }
            self.tasks[t].weight = weight;
            self.weight_total = (self.weight_total as i128 + weight as i128 - old as i128) as u64;
            let g = self.tasks[t].group;
            self.touch_group(g);
            self.load[g] = (self.load[g] as i128 + weight as i128 - old as i128) as u64;
            self.refresh_work(g);
        }
        Edit::Class(t, class) => {
            if t >= self.tasks.len() || class > u32::MAX as u64 { return; }
            self.touch_task(t);
            let old = self.tasks[t].class;
            if old == class { return; }
            let g = self.tasks[t].group;
            let domain = self.domain[self.tasks[t].template];
            self.pair_dec(g, pair_key(domain, old));
            self.pair_inc(g, pair_key(domain, class));
            self.tasks[t].class = class;
        }
        Edit::Bind(t, template) => {
            if t >= self.tasks.len() || template * self.words + self.words > self.fp.len() { return; }
            self.touch_task(t);
            let old = self.tasks[t].template;
            if old == template { return; }
            let g = self.tasks[t].group;
            let class = self.tasks[t].class;
            self.attach(old, g, false);
            self.attach(template, g, true);
            let before = pair_key(self.domain[old], class);
            let after = pair_key(self.domain[template], class);
            if before != after {
                self.pair_dec(g, before);
                self.pair_inc(g, after);
            }
            self.tasks[t].template = template;
        }
        Edit::Pin(t, pinned) => {
            if t >= self.tasks.len() { return; }
            self.touch_task(t);
            if self.tasks[t].pinned != pinned {
                self.tasks[t].pinned = pinned;
                if pinned { self.pinned_total += 1; } else { self.pinned_total -= 1; }
            }
        }
        Edit::Quota(g, quota) => {
            if g >= self.groups { return; }
            self.touch_group(g);
            let old = self.quota[g];
            if old == quota { return; }
            self.quota[g] = quota;
            let base = g * self.n;
            for v in 0..self.n {
                if self.cnt[base + v] > 0 {
                    let next = self.usage[v] - old + quota;
                    self.set_usage(v, next);
                }
            }
            self.refresh_work(g);
        }
        Edit::Budget(g, budget) => {
            if g >= self.groups { return; }
            self.touch_group(g);
            self.budget[g] = budget;
            self.refresh_work(g);
        }
        Edit::Cap(v, cap) => {
            if v >= self.n { return; }
            self.touch_node(v);
            self.caps[v] = cap;
            let over = self.usage[v] > cap;
            if over != self.over[v] {
                self.over[v] = over;
                if over { self.cap_v += 1; } else { self.cap_v -= 1; }
            }
        }
    }
}

fn begin_tx(&mut self) {
    self.tx = self.tx.wrapping_add(1);

